variants.typescript:
Find all the bugs in this code:

```typescript
interface Product {
  name: string;
  price: number;
  quantity: number;
}

function calculateTotal(products: Product[]): number {
  let total = 0;

  for (const product of products) {
    // BUG: If quantity comes from user input, it might be a string
    total += product.price * product.quantity;
  }

  return total;
}

function applyDiscount(total: number, discount: string): number {
  // BUG: discount is a string, will concatenate instead of subtract
  return total - discount;
}

function formatPrice(price: number): string {
  return '$' + price.toFixed(2);
}

// Usage
const products: Product[] = [
  { name: 'Item 1', price: 10, quantity: '2' as any },  // quantity is actually a string!
  { name: 'Item 2', price: 20, quantity: 1 }
];

const total = calculateTotal(products);
const discounted = applyDiscount(total, '5');  // BUG: passing string
console.log(formatPrice(discounted));
```

Identify all bugs and explain how TypeScript could help catch them.

